const dispOut  = ($input.first().json.text || '').trim();
const initData = $('Record Start Time').item.json;
const VALID    = ['theory', 'practice', 'critique'];
const MAX_ITER = 5;
let parsed     = { primary_agent: 'theory', routing_rationale: 'Fallback — parse error' };
let fallback   = false;

try {
  const m = dispOut.match(/\{[\s\S]*\}/);
  if (m) {
    const p = JSON.parse(m[0]);
    if (p && VALID.includes(p.primary_agent)) { parsed = p; }
    else { fallback = true; }
  } else { fallback = true; }
} catch(e) { fallback = true; }

const g = $getWorkflowStaticData('global');
g.swarm_state = {
  current_agent:             parsed.primary_agent,
  handoff_instruction:       '',
  accumulated_work:          [],
  routing_rationale:         parsed.routing_rationale,
  dispatcher_token_estimate: Math.ceil(dispOut.length / 4),
  max_iterations:            MAX_ITER,
  input_text:                initData.input_text,
  start_time_ms:             initData.start_time_ms,
  input_token_estimate:      initData.input_token_estimate,
  parse_fallback_used:       fallback
};

return [{ json: {
  input_text:           initData.input_text,
  start_time_ms:        initData.start_time_ms,
  input_token_estimate: initData.input_token_estimate,
  max_iterations:       MAX_ITER
}}];

const init = $input.first().json;
const MAX  = init.max_iterations || 5;
return Array.from({ length: MAX }, (_, i) => ({
  json: {
    iteration:            i + 1,
    input_text:           init.input_text,
    start_time_ms:        init.start_time_ms,
    input_token_estimate: init.input_token_estimate
  }
}));

const slot  = $input.first().json;
const g     = $getWorkflowStaticData('global');
const state = g.swarm_state || {};

const PROFILES = {
  theory:   { role: 'Theory Specialist',   expertise: 'theoretical foundations, academic definitions, conceptual models and scholarly consensus',  can_contribute: 'definitional clarity, historical context, theoretical frameworks' },
  practice: { role: 'Practice Specialist', expertise: 'real-world applications, system implementations, case studies and practical impact',        can_contribute: 'concrete examples, implementation patterns, operational considerations' },
  critique: { role: 'Critique Specialist', expertise: 'limitations, trade-offs, risks, failure modes and critical analysis',                       can_contribute: 'risk assessment, failure analysis, trade-off evaluation' }
};

const activeAgent = state.current_agent || 'theory';
const profile     = PROFILES[activeAgent] || PROFILES.theory;
const prevWork    = state.accumulated_work || [];
const hopsLeft    = (state.max_iterations || 5) - slot.iteration;

const peers = Object.entries(PROFILES)
  .filter(([k]) => k !== activeAgent)
  .map(([k, v]) => `• "${k}" (${v.role}): contributes ${v.can_contribute}`)
  .join('\n');

const prevWorkText = prevWork.length > 0
  ? prevWork.map((w, i) =>
      `[Turn ${i + 1} — ${w.role} | level: ${w.contribution_level}]\n` +
      (w.response ? w.response : '(skipped — domain already covered)')
    ).join('\n\n---\n\n')
  : 'No prior work yet — you are the first agent in this swarm.';

return [{ json: {
  iteration:                    slot.iteration,
  active_agent:                 activeAgent,
  active_role:                  profile.role,
  active_expertise:             profile.expertise,
  active_can_contribute:        profile.can_contribute,
  peer_descriptions:            peers,
  accumulated_work:             prevWork,
  accumulated_work_text:        prevWorkText,
  handoff_instruction_received: state.handoff_instruction || '',
  hops_remaining:               hopsLeft,
  max_iterations:               state.max_iterations || 5,
  routing_rationale:            state.routing_rationale || '',
  dispatcher_token_estimate:    state.dispatcher_token_estimate || 0,
  input_text:                   slot.input_text,
  start_time_ms:                slot.start_time_ms,
  input_token_estimate:         slot.input_token_estimate
}}];

