const rawOutput = ($input.first().json.text || '').trim();
const ctx       = $('Prepare Agent Context').item.json;
const slot      = $('Loop Over Items').item.json;
const g         = $getWorkflowStaticData('global');
const state     = g.swarm_state || {};

const VALID_L = ['full', 'partial', 'skip'];
const VALID_T = ['theory', 'practice', 'critique'];
let fallback  = false;
let parsed    = { contribution_level: 'partial', response: rawOutput,
                  needs_handoff: false, handoff_target: 'none', handoff_instruction: '' };

try {
  const m = rawOutput.match(/\{[\s\S]*\}/);
  if (m) {
    const p = JSON.parse(m[0]);
    if (p && VALID_L.includes(p.contribution_level)) { parsed = p; }
    else { fallback = true; }
  } else { fallback = true; }
} catch(e) { fallback = true; }

parsed.contribution_level  = VALID_L.includes(parsed.contribution_level) ? parsed.contribution_level : 'partial';
parsed.needs_handoff       = !!parsed.needs_handoff;
parsed.handoff_target      = VALID_T.includes(parsed.handoff_target) ? parsed.handoff_target : 'none';
parsed.handoff_instruction = parsed.handoff_instruction || '';

if (parsed.handoff_target === ctx.active_agent) {
  parsed.handoff_target = 'none'; parsed.needs_handoff = false;
}
if (parsed.handoff_target === 'none') { parsed.needs_handoff = false; }

const capReached = slot.iteration >= (state.max_iterations || 5);
const agentDone  = !parsed.needs_handoff;
const isDone     = capReached || agentDone;
const termReason = capReached ? 'max_iterations_safety_cap' : (agentDone ? 'agent_decided_complete' : 'continue');

const newWork = [...(state.accumulated_work || []), {
  agent:              ctx.active_agent,
  role:               ctx.active_role,
  iteration:          slot.iteration,
  contribution_level: parsed.contribution_level,
  response:           parsed.contribution_level !== 'skip' ? (parsed.response || '').trim() : ''
}];

g.swarm_state = {
  ...state,
  current_agent:       parsed.needs_handoff ? parsed.handoff_target : ctx.active_agent,
  handoff_instruction: parsed.handoff_instruction,
  accumulated_work:    newWork
};

return [{ json: {
  is_done:            isDone,
  termination_reason: termReason,
  iteration:          slot.iteration,
  active_agent:       ctx.active_agent,
  contribution_level: parsed.contribution_level,
  needs_handoff:      parsed.needs_handoff,
  handoff_target:     parsed.handoff_target,
  token_estimate:     Math.ceil(rawOutput.length / 4),
  accumulated_work:   newWork,
  routing_rationale:  state.routing_rationale || '',
  dispatcher_token_estimate: state.dispatcher_token_estimate || 0,
  input_text:         ctx.input_text,
  start_time_ms:      ctx.start_time_ms,
  input_token_estimate: ctx.input_token_estimate
}}];

const s     = $input.first().json;
const g     = $getWorkflowStaticData('global');
const state = g.swarm_state || {};
const all   = state.accumulated_work || [];
const real  = all.filter(w => w.contribution_level !== 'skip' && w.response);
const text  = real.map(w =>
  `--- Turn ${w.iteration}: ${w.role} [${w.contribution_level}] ---\n${w.response}`
).join('\n\n');

return [{ json: {
  accumulated_work:          all,
  active_contributions:      real,
  contributions_text:        text,
  contributor_count:         real.length,
  total_iterations:          s.iteration,
  handoff_chain:             all.map(w => w.agent).join(' → '),
  termination_reason:        s.termination_reason,
  routing_rationale:         state.routing_rationale || '',
  dispatcher_token_estimate: state.dispatcher_token_estimate || 0,
  input_text:                s.input_text,
  start_time_ms:             s.start_time_ms,
  input_token_estimate:      s.input_token_estimate
}}];

