const endMs    = Date.now();
const coll     = $('Loop Collector').item.json;
const synthTxt = ($input.first().json.text || '').trim();
const synthTok = Math.ceil(synthTxt.length / 4);
const agentTok = (coll.accumulated_work || []).reduce((s, w) => s + Math.ceil((w.response || '').length / 4), 0);
const dispTok  = coll.dispatcher_token_estimate || 0;
const inpTok   = coll.input_token_estimate || 0;
const latMs    = endMs - coll.start_time_ms;

const totalIterations = coll.total_iterations || 0;
const llmCallsActual  = totalIterations + 2;
const llmCallsMax     = 7;

const totalInputTok  = inpTok + dispTok;
const totalOutputTok = dispTok + agentTok + synthTok;
const totalTok       = inpTok + dispTok + agentTok + synthTok;

return [{ json: {

  user_prompt:  coll.input_text,
  final_answer: synthTxt,

  metadata: {
    pattern:           'Swarm — Loop-Based (splitInBatches)',
    pattern_category:  'AI-Orchestrated Multi-Agent Pattern — Decentralised Swarm',
    run_timestamp:     new Date().toISOString(),
    model:             'qwen2.5:14b',
    model_provider:    'Ollama (local)',
    latency_ms:        latMs,
    latency_seconds:   parseFloat((latMs / 1000).toFixed(2)),
    llm_calls_actual:  llmCallsActual,
    llm_calls_max:     llmCallsMax,
    token_usage: {
      total_input_tokens:  totalInputTok,
      total_output_tokens: totalOutputTok,
      total_tokens:        totalTok
    },
    status:             'completed',
    termination_reason: coll.termination_reason || 'unknown'
  },

  execution_trace: {

    dispatcher: {
      primary_agent_chosen:  (coll.accumulated_work && coll.accumulated_work[0]) ? coll.accumulated_work[0].agent : 'unknown',
      routing_rationale:     coll.routing_rationale,
      token_estimate:        dispTok
    },

    swarm_turns: (coll.accumulated_work || []).map(w => ({
      turn:               w.iteration,
      agent:              w.agent,
      role:               w.role,
      contribution_level: w.contribution_level,
      output:             w.response || '',
      token_estimate:     Math.ceil((w.response || '').length / 4),
      contributed:        w.contribution_level !== 'skip'
    })),

    synthesis: {
      output:         synthTxt,
      token_estimate: synthTok
    },

    swarm_summary: {
      handoff_chain:     coll.handoff_chain,
      total_iterations:  totalIterations,
      contributors:      coll.contributor_count,
      exited_early:      totalIterations < 5,
      termination_reason: coll.termination_reason
    },

    structural_properties: {
      orchestration_type:  'decentralised — dispatcher routes first agent; agents self-direct all subsequent turns',
      peer_awareness:      'all agents know peer specialties before each turn',
      revisit_policy:      'any agent can be re-contacted any number of times — only self-referral blocked',
      contribution_model:  'full | partial | skip, re-evaluated every turn',
      termination_logic:   'dual: agent outputs needs_handoff=false (AI-driven) OR iteration cap reached (code-enforced)',
      loop_mechanism:      'splitInBatches (Loop Over Items) with loop-back edge from Exit Gate',
      state_passing:       '$getWorkflowStaticData(global) carries accumulated_work, current_agent and handoff_instruction between iterations',
      max_iterations:      5,
      actual_iterations:   totalIterations,
      pattern_category:    'AI-Orchestrated Multi-Agent Pattern — Decentralised Swarm'
    },

    llm_limitation: 'n8n Ollama node (lmChatOllama typeVersion 1) does not expose a temperature parameter. Temperature is governed by the Ollama server default (typically 0.8). To override it, set the value in the Ollama Modelfile or replace the native Ollama node with an HTTP Request node and pass temperature in the request body.'
  }

}}];
